@GetMapping(value = "/generate/stream", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
public SseEmitter generateStream(@AuthenticationPrincipal Long userId) {
    SseEmitter emitter = new SseEmitter(300_000L); // 5분 타임아웃

    // 별도 스레드에서 실행 (메인 스레드 블로킹 방지)
    CompletableFuture.runAsync(() -> {
        try {
            // 1. COLLECT
            sendEvent(emitter, ProgressEvent.collectStart(topInvestments));
            List<CollectResult> results = newsCollectorService.collect(userId,
                result -> sendEvent(emitter, ProgressEvent.collectProgress(result)));
            sendEvent(emitter, ProgressEvent.collectDone(results));

            // 2. EMBED
            sendEvent(emitter, ProgressEvent.embedStart());
            newsCollectorService.embedAll(
                progress -> sendEvent(emitter, ProgressEvent.embedProgress(progress)));
            sendEvent(emitter, ProgressEvent.embedDone());

            // 3. REPORT
            sendEvent(emitter, ProgressEvent.reportStart());
            DailyReport report = dailyReportService.generateDailyReport(userId);
            sendEvent(emitter, ProgressEvent.reportComplete(report));

            emitter.complete();
        } catch (Exception e) {
            sendEvent(emitter, ProgressEvent.error(e.getMessage()));
            emitter.completeWithError(e);
        }
    });

    return emitter;
}

