const eventSource = new EventSource('/api/daily-report/generate/stream', {
    withCredentials: true
})

eventSource.onmessage = (e) => {
    const event = JSON.parse(e.data)

    switch(event.type) {
        case 'COLLECT':
            if (event.status === 'PROGRESS') {
                // 종목별 수집 현황 업데이트
                updateCollectStatus(event.stockName, event.message)
            }
            break
        case 'EMBED':
            if (event.status === 'PROGRESS') {
                // 요약본 카드 하나씩 추가
                addSummaryCard(event.data.title, event.data.summary)
                updateProgress(event.current, event.total)
            }
            break
        case 'REPORT':
            if (event.status === 'COMPLETE') {
                // 리포트 표시
                showReport(event.data)
                eventSource.close()
            }
            break
    }
}

